				// 타이틀 지급 (memberTitlePath 방식 / 중복 방지)
				function grantTitleToUser(userName, titleName, price) {
					try {
						var titleData = loadJsonFile(memberTitlePath);
						if (!titleData.member) titleData.member = {};
						if (!titleData.member[userName]) titleData.member[userName] = { title: { list: [], num: null } };
						if (!titleData.member[userName].title) titleData.member[userName].title = { list: [], num: null };
						if (!titleData.member[userName].title.list) titleData.member[userName].title.list = [];

						var list = titleData.member[userName].title.list;

						for (var i = 0; i < list.length; i++) {
							if (list[i] && list[i].name === titleName) return false;
						}

						list.push({
							name: titleName,
							inDate: new Date().toISOString(),
							price: price
						});

						saveJsonFile(titleData, memberTitlePath);
						return true;
					} catch (e) {
						return false;
					}
				}

