					if (!matchBagsell) {
						replier.reply("올바른 명령어 형식을 사용해주세요.\n예: /판매 [아이템번호] [수량]");
						return;
					}

					const itemIndex = parseInt(matchBagsell[1], 10) - 1;
					const quantityToSell = parseInt(matchBagsell[2], 10);
					let memberInfo = data.member && data.member[sender] ? data.member[sender] : null;
					if (!memberInfo) return;

					let bagItems = memberInfo.bag || {};
					var itemListData = loadJsonFile(itemListPath);
