/**
 * 세율을 적용하고 성주에게 포인트를 추가하는 함수
 * @param {number} point - 세율이 적용될 포인트
 * @returns {number} - 세금이 적용된 후의 포인트
 */
function applyTax(point, data, guildData) {
	// 세율과 성주 정보가 있는지 확인
	if (data.HoiCastle && data.HoiCastle.taxRate && data.HoiCastle.lord) {
		var taxRate = data.HoiCastle.taxRate; // 세율
		var lord = data.HoiCastle.lord; // 성주

		// 세금 계산
		var taxAmount = Math.round(point * (taxRate / 100));
		var taxedPoint = point + taxAmount;

		// 실제 길드자금으로 들어갈 금액
		var guildFundAmount = Math.round(taxAmount * 0.5); // 세금의 50%가 길드자금으로 들어감

		// 성주의 길드 찾기
		var myGuildInfo = getMyGuildInfo(data, guildData, lord);

		if (myGuildInfo && !myGuildInfo.error && myGuildInfo.guild) {
			var g = myGuildInfo.guild;

			ensureGuildWarehouseObj(g);

			g.warehouse.fund += guildFundAmount;
		}

		// 호월킹덤 누적 수익
		if (typeof data.HoiCastle.earnings !== "number") {
			data.HoiCastle.earnings = 0;
		}
		data.HoiCastle.earnings += guildFundAmount;

		// 세금이 적용된 금액 반환
		saveJsonFile(guildData, guildPath);
		return taxedPoint;
	} else {
		return point;
	}
}

