	if (exp >= 10010000) return 12; // 1001만~1500만
	if (exp >= 9510000) return 11; // 951만~1000만
	if (exp >= 9010000) return 10.5; // 901만~950만
	if (exp >= 8510000) return 10; // 851만~900만
