// 길드의 총 매력 계산 (길드원들의 총 매력 합산)
function calculateGuildTotalExp(guild, data, petData, homeData, petSkillData) {
	if (!guild || !guild.members) return 0;

	var total = 0;
	var user;

	for (user in guild.members) {
		if (!guild.members.hasOwnProperty(user)) continue;
		total += calculateTotalExp(user, data, petData, homeData, petSkillData) || 0;
	}

	total = parseInt(total, 10);
	if (isNaN(total)) total = 0;

	return total;
}

// 길드 랭킹용 행 데이터 생성 (길드명, 길드마크, 서버명, 길드마스터, 길드레벨, 총 매력 등)
function buildGuildRankingRows(guildData, data, petData, homeData, petSkillData) {
	var rows = [];
	var gid;
	var guild;
	var title;

	if (!guildData || !guildData.guilds) return rows;

	for (gid in guildData.guilds) {
		if (!guildData.guilds.hasOwnProperty(gid)) continue;

		guild = guildData.guilds[gid];
		if (!guild) continue;

		rows.push({
			gid: gid,
			name: guild.name || gid,
			mark: guild.mark || "",
			server: guild.server || "",
			master: guild.master || "없음",
			level: guild.level || 1,
			totalCharm: calculateGuildTotalExp(guild, data, petData, homeData, petSkillData)
		});
	}

	rows.sort(function (a, b) {
		if (b.totalCharm !== a.totalCharm) {
			return b.totalCharm - a.totalCharm;
		}

		if ((b.level || 0) !== (a.level || 0)) {
			return (b.level || 0) - (a.level || 0);
		}

		return String(a.name).localeCompare(String(b.name), "ko");
	});

	// 순위 데이터 반영
	for (var i = 0; i < rows.length; i++) {
		gid = rows[i].gid;
		guild = guildData.guilds[gid];

		if (!guild) continue;

		title = getGuildMasterRankTitle(i + 1);

		rows[i].rank = i + 1;
		rows[i].rankTitle = title;

		guild.rank = i + 1;
		guild.rankTitle = title;
	}

	return rows;
}

// 길드 랭킹 보상 테이블 반환 (1등 100개 → 20등 8개)
