// 길드 랭킹 보상 지급 처리 함수
function runGuildRankReward(data, petData, guildData, homeData, petSkillData) {
	var rewardItemName = "펫스윗홈인테리어샵🖼️(/샵오픈)";
	var rewardTable = getGuildRankRewardTable();
	var rows = buildGuildRankingRows(guildData, data, petData, homeData, petSkillData).slice(0, rewardTable.length);
	var result = {
		rewardItemName: rewardItemName, // 보상 아이템명
		rows: rows, // 랭킹 보상 대상 길드 데이터 (길드명, 길드마크, 서버명, 길드마스터, 길드레벨, 총 매력, 순위 등)
		results: [], // 지급 결과 배열 (길드별로 지급된 유저 목록과 제외된 유저 목록 포함)
		totalPaidUsers: 0, // 총 지급된 유저 수
		totalSkippedUsers: 0 // 총 제외된 유저 수
	};

	if (!rows.length) {
		result.error = "NO_GUILD";
		return result;
	}

	for (var i = 0; i < rows.length; i++) {
		var row = rows[i];
		var rewardInfo = rewardTable[i];
		var guild = guildData && guildData.guilds ? guildData.guilds[row.gid] : null;
		var members = guild && guild.members ? Object.keys(guild.members) : [];
		var paidUsers = [];
		var skippedUsers = [];

		for (var j = 0; j < members.length; j++) {
			var userName = members[j];
			var memberData = data.member ? data.member[userName] : null;

			if (!memberData) {
				skippedUsers.push(userName + "(데이터없음)");
				continue;
			}

			if (!memberData.guild || memberData.guild.id !== row.gid) {
				skippedUsers.push(userName + "(길드불일치)");
				continue;
			}

			addItem(data, userName, rewardItemName, rewardInfo.count);
			paidUsers.push(userName);
			result.totalPaidUsers++;
		}

		result.totalSkippedUsers += skippedUsers.length;
		result.results.push({
			rank: rewardInfo.rank,
			gid: row.gid,
			name: row.name,
			mark: row.mark || "",
			count: rewardInfo.count,
			paidUsers: paidUsers,
			skippedUsers: skippedUsers
		});
	}

	return result;
}

// 길드 랭킹 보상 지급 결과 메시지 생성 함수
function buildGuildRankRewardPayoutMessage(payoutResult) {
	var lines = [];
	var rewardItemName = payoutResult.rewardItemName;
	var rows = payoutResult.results || [];

	lines.push("🎖️길드순위 보상지급🎖️");
	lines.push("[1등~20등의 길드원에게만 지급됩니다.]");
	lines.push("");

	for (var i = 0; i < rows.length; i++) {
		var row = rows[i];
		lines.push(row.rank + "등 " + row.name + (row.mark || ""));
		lines.push(rewardItemName + " " + row.count + "개");
		lines.push("지급: " + row.paidUsers.length + "명 / 제외: " + row.skippedUsers.length + "명");

		if (row.skippedUsers.length > 0) {
			lines.push("제외대상: " + row.skippedUsers.join(", "));
		}

		if (i === 4 && rows.length > 5) {
			lines.push("6등~20등 보상 확인하기.. // + alllsee");
			lines.push(allsee);
		}

		lines.push("");
	}

	lines.push("총 지급 인원: " + payoutResult.totalPaidUsers + "명");
	lines.push("총 제외 인원: " + payoutResult.totalSkippedUsers + "명");

	return lines.join("\n").trim();
}

// 길드명 → 길드ID 매핑 재생성 (guildData.guilds 기반으로 guildData.nameToId 다시 구축)
function rebuildGuildNameToId(guildData) {
	guildData.nameToId = {};

	for (var gid in guildData.guilds) {
		if (!guildData.guilds.hasOwnProperty(gid)) continue;

		var g = guildData.guilds[gid];
		if (!g || !g.name) continue;

		guildData.nameToId[g.name] = gid;
	}
}

// guild ↔ member 불일치 복구 및 중복 소속 정리
function removeMemberFromAllGuilds(guildData, sender) {
	if (!guildData || !guildData.guilds) return 0;

	var removed = 0;
	for (var gid in guildData.guilds) {
		if (!guildData.guilds.hasOwnProperty(gid)) continue;
		var g = guildData.guilds[gid];
		if (!g || !g.members) continue;

		if (g.members[sender]) {
			delete g.members[sender];
			removed++;
		}
	}
	return removed;
}

// 길드명 유효성 검사 - 공백 포함 불가, 글자 1~10개
function isValidGuildName(guildName) {
	guildName = String(guildName || "").trim();
	if (!guildName) return false;
	if (guildName.indexOf(" ") >= 0) return false; // 공백 불가
	return guildName.length >= 1 && guildName.length <= 30; // 1~10자
}

// 길드 데이터 동기화: guildData.guilds 기준으로 data.member의 guild 참조 재설정 및 중복/누락 검토
function syncMemberGuild(data, guildData) {
	if (!data || !data.member || !guildData || !guildData.guilds) {
		return {
			success: false,
			message: "data 또는 guildData 구조가 올바르지 않습니다."
		};
	}

	var syncedCount = 0;
	var missingMembers = [];
	var duplicatedMembers = [];
	var seen = {};

	// 1. 전체 member.guild 초기화
	for (var memberName in data.member) {
		if (!data.member.hasOwnProperty(memberName)) continue;
		if (!data.member[memberName]) continue;

		data.member[memberName].guild = null;
	}

	// 2. guildData 기준으로 다시 세팅
	for (var guildId in guildData.guilds) {
		if (!guildData.guilds.hasOwnProperty(guildId)) continue;

		var guild = guildData.guilds[guildId];
		if (!guild || !guild.members) continue;

		for (var name in guild.members) {
			if (!guild.members.hasOwnProperty(name)) continue;

			var memberInfo = guild.members[name] || {};

			if (!data.member[name]) {
				missingMembers.push(name + " -> guildId:" + guildId);
				continue;
			}

			if (seen[name]) {
				duplicatedMembers.push(name + " -> " + seen[name] + "," + guildId);
				continue;
			}

			data.member[name].guild = {
				id: guildId,
				role: memberInfo.role || "MEMBER",
				contribution: typeof memberInfo.contribution === "number" ? memberInfo.contribution : 0
			};

			seen[name] = guildId;
			syncedCount++;
		}
	}

	return {
		success: true,
		syncedCount: syncedCount,
		missingMembers: missingMembers,
		duplicatedMembers: duplicatedMembers
	};
}

// 만, 억단위

function formatKoreanShort(num) {
	num = Number(num) || 0;

	if (num >= 100000000) {
		var man = Math.floor(num / 10000); // 만 단위
		var eok = Math.floor(num / 100000000); // 억 단위

		return numberWithCommas(man) + "만(" + eok + "억)";
	}

	if (num >= 10000) {
		var man = Math.floor(num / 10000);
		return numberWithCommas(man) + "만";
	}

	return numberWithCommas(num);
}

//인증순위
function buildCheckCntRanking(data) {
	var result = [];

	for (var name in data.member) {
		if (!data.member.hasOwnProperty(name)) continue;

		var cnt = data.member[name].checkCnt || 0;
		if (cnt <= 0) continue; // 0회 제외

		result.push({
			name: name,
			cnt: cnt
		});
	}

	// 정렬: 인증 횟수 높은 순 → 이름 오름차순
	result.sort(function (a, b) {
		if (b.cnt !== a.cnt) return b.cnt - a.cnt;
		return a.name.localeCompare(b.name, "ko");
	});

	return result;
}

// 길드 게시판 날짜 포맷 (MM/DD HH:mm)
function formatBoardDate(date) {
	if (!date) date = new Date();

	var mm = String(date.getMonth() + 1);
	var dd = String(date.getDate());
	var hh = String(date.getHours());
	var mi = String(date.getMinutes());

	if (mm.length < 2) mm = "0" + mm;
	if (dd.length < 2) dd = "0" + dd;
	if (hh.length < 2) hh = "0" + hh;
	if (mi.length < 2) mi = "0" + mi;

	return mm + "/" + dd + " " + hh + ":" + mi;
}

// 길드 게시판 데이터 구조 보장 (board 객체 및 notice, posts 배열 초기화)
function ensureGuildBoard(g) {
	if (!g.board) g.board = {};
	if (!g.board.notice) g.board.notice = null;
	if (!g.board.posts) g.board.posts = [];
}

// 길드 게시판에 새 글 추가
function isGuildMaster(g, sender) {
	return g && g.master === sender;
}

// data.member 기준으로 다른 객체의 유저 키를 정리하는 공통 함수
function syncByMemberKeys(originMemberObj, targetObj) {
	var originKeys = Object.keys(originMemberObj || {});
	var targetKeys = Object.keys(targetObj || {});
	var removed = [];

	targetKeys.forEach(function (key) {
		if (originKeys.indexOf(key) === -1) {
			removed.push(key);
			delete targetObj[key];
		}
	});

	return removed;
}

function buildMiniPetBagMessage(targetName, viewerName, data, petData, guildData, miniPetData) {
	if (!petData[targetName]) {
		return "해당 유저의 미니펫 데이터가 없습니다.";
	}
	if (!petData[targetName].miniPetBag) {
		petData[targetName].miniPetBag = [];
	}

	refreshMiniPetSortIndex(petData, targetName, miniPetData.gradeTable);

	let bag = petData[targetName].miniPetBag;
	let equipped = petData[targetName].miniPet;
	let nickname = checkRank(data, petData, guildData, targetName);

	if (bag.length === 0 && !equipped) {
		return "[" + nickname + "] 님은 미니펫을 보유하고 있지 않습니다.";
	}

	let totalExp = getTotalMinipetExp(targetName, petData);
	let rank = getMiniPetTotalExpRank(targetName, petData);

	let battle = petData[targetName].miniPetBattle || {
		win: 0,
		lose: 0,
		count: 0
	};

	let totalBattle = battle.win + battle.lose;
	let winPercent = totalBattle > 0 ? Math.round((battle.win / totalBattle) * 100) : 0;
	let battleRank = getMiniPetBattleRank(targetName, petData);
	let remainBattle = battle.count || 0;

	// 미니펫 타이틀 / 컬렉션 단계 조회
	let miniPetTitleName = "미니펫타이틀이 없슴다";
	let completedStage = 0;
	let collectionRegisteredCount = 0;
	let collectionMaxCount = 0;
	let collectionRankText = "순위없음📊";

	var miniPetTitleData = loadJsonFile(miniPetTitlePath);
	var miniPetCollectionData = loadJsonFile(miniPetCollectionPath);

	if (miniPetTitleData && miniPetTitleData.member && miniPetTitleData.member[targetName] && miniPetTitleData.member[targetName].title) {
		var userTitle = miniPetTitleData.member[targetName].title;
		var titleNum = userTitle.num;

		if (titleNum != null && userTitle.list && userTitle.list[titleNum - 1]) {
			miniPetTitleName = userTitle.list[titleNum - 1].name;
		}
	}

	if (miniPetCollectionData && miniPetCollectionData.member && miniPetCollectionData.member[targetName] && miniPetCollectionData.member[targetName].collection) {
		completedStage = miniPetCollectionData.member[targetName].collection.completedStage || 0;
	}

	var collectionRow = getMiniPetCollectionData(miniPetCollectionData, targetName);
	if (collectionRow) {
		completedStage = collectionRow.completedStage || 0;
		collectionRegisteredCount = collectionRow.registeredCount || 0;
		collectionMaxCount = collectionRow.maxCount || 0;
	}

	var collectionRanking = getMiniPetCollectionRanking(miniPetCollectionData);
	for (var rankIndex = 0; rankIndex < collectionRanking.length; rankIndex++) {
		if (collectionRanking[rankIndex].userName === targetName) {
			collectionRankText = rankIndex + 1 + "등📊";
			break;
		}
	}

	let output = "";

	// 관리자 조회일 때만 헤더 추가
	if (viewerName && viewerName !== targetName) {
		output += "🔎 미니펫정보\n";
		output += "조회자: " + viewerName + "\n";
		output += "대상: " + targetName + "\n\n";
	}

	output += "✮━" + miniPetTitleName + "━✮\n";
	output += "[" + nickname + "]의 미니펫 가방[" + bag.length + "/12소장]\n";
	output += "미니펫컬렉션+" + completedStage + "💫[" + collectionRegisteredCount + "/" + collectionMaxCount + "] (" + collectionRankText + ")\n\n";
	output += "총매력💞: " + numberWithCommas(totalExp) + "💕(" + rank + "🐹)\n";

	if (equipped) {
		output += "미니펫🐹: " + equipped.name + equipped.emoji;
		output += "(+" + numberWithCommas(equipped.battleExp || 0) + "💕)";
		output += "[" + equipped.grade + "]";
		output += (equipped.upgrade ? "(" + getMiniPetUpgradeDisplay(equipped) + "💫)" : "") + "\n";
	}

	output += "미대전🆚: " + battle.win + "승 " + battle.lose + "패(" + winPercent + "%)(" + battleRank + ")\n";
	output += "미대전 횟수(" + remainBattle + "/10)*무료 3회가능\n";
	output += "(미니펫장착+5개 총매력이 적용됩니다.)\n";
	output += "━━━━━━━━━━━━━━━\n";

	for (let i = 0; i < bag.length; i++) {
		if (i === 3 && typeof allsee !== "undefined") {
			output += allsee;
		}

		let pet = bag[i];
		output += pet.sortIndex + ". " + pet.name + pet.emoji;
		output += "(+" + numberWithCommas(pet.battleExp || 0) + "💕)[" + pet.grade + "]";
		output += (pet.upgrade ? "(" + getMiniPetUpgradeDisplay(pet) + "💫)" : "") + "\n";
	}

	return output.trim();
}

