// 가구 정보 문자열 생성 (예: "소파(매력💕)[등급]")
function getFurnitureDisplay(furniture) {
	if (!furniture) return "";
	return furniture.name + "(+" + numberWithCommas(furniture.exp) + "💕)" + "[" + furniture.grade + "]";
}

// 유저의 title 구조가 없으면 생성하고 안전하게 반환
function ensureTitleUser(titleData, sender) {
	if (!titleData.member) {
		titleData.member = {};
	}

	if (!titleData.member[sender]) {
		titleData.member[sender] = {};
	}

	if (!titleData.member[sender].title) {
		titleData.member[sender].title = {
			list: [],
			num: null
		};
	}

	return titleData.member[sender].title;
}

// 같은 이름의 타이틀이 이미 있으면 false
function addTitle(titleData, userName, titleName, price) {
	var userTitle = ensureTitleUser(titleData, userName);
	var i;

	for (i = 0; i < userTitle.list.length; i++) {
		if (userTitle.list[i].name === titleName) {
			return false;
		}
	}

	userTitle.list.push({
		name: titleName,
		inDate: new Date().toISOString(),
		price: price || 0
	});

	if (userTitle.num == null) {
		userTitle.num = 1;
	}

	return true;
}

// 미니펫 컬렉션 등록 가능한 등급인지 확인하는 함수
function isMiniPetCollectionGradeAllowed(grade) {
	return MINI_PET_COLLECTION_ALLOWED_GRADES.indexOf(grade) !== -1;
}

// 미니펫 컬렉션 등록 상태 초기값 생성 함수 (허용된 등급만 false로 초기화)
function createMiniPetCollectionRegistered() {
	var registered = {};
	for (var i = 0; i < MINI_PET_COLLECTION_ALLOWED_GRADES.length; i++) {
		registered[MINI_PET_COLLECTION_ALLOWED_GRADES[i]] = false;
	}
	return registered;
}

// 미니펫 컬렉션 등록 상태 정규화 함수 (허용된 등급만, 누락된 등급은 false로 채움)
function normalizeMiniPetCollectionRegistered(registered) {
	var normalized = createMiniPetCollectionRegistered();
	if (!registered || typeof registered !== "object") {
		return normalized;
	}

	for (var i = 0; i < MINI_PET_COLLECTION_ALLOWED_GRADES.length; i++) {
		var grade = MINI_PET_COLLECTION_ALLOWED_GRADES[i];
		normalized[grade] = registered[grade] === true;
	}

	return normalized;
}

// 미니펫 컬렉션 데이터 구조 보장 및 등록 상태 정규화 (collectionData.member[userName].collection.registered)
function sanitizeMiniPetCollectionData(collectionData) {
	if (!collectionData || typeof collectionData !== "object") {
		return false;
	}

	if (!collectionData.member || typeof collectionData.member !== "object") {
		collectionData.member = {};
		return true;
	}

	var changed = false;
	for (var userName in collectionData.member) {
		if (!collectionData.member.hasOwnProperty(userName)) continue;

		var userData = collectionData.member[userName];
		if (!userData || !userData.collection) continue;

		var normalized = normalizeMiniPetCollectionRegistered(userData.collection.registered);
		var before = JSON.stringify(userData.collection.registered || {});
		var after = JSON.stringify(normalized);

		if (before !== after) {
			userData.collection.registered = normalized;
			changed = true;
		}
	}

	return changed;
}

// 유저의 미니펫 컬렉션 구조가 없으면 생성하고 안전하게 반환
function ensureMiniPetCollection(collectionData, sender) {
	if (!collectionData.member) {
		collectionData.member = {};
	}

	if (!collectionData.member[sender]) {
		collectionData.member[sender] = {};
	}

	if (!collectionData.member[sender].collection) {
		collectionData.member[sender].collection = {
			stage: 1,
			completedStage: 0,
			registered: createMiniPetCollectionRegistered()
		};
	}

	collectionData.member[sender].collection.registered = normalizeMiniPetCollectionRegistered(collectionData.member[sender].collection.registered);

	return collectionData.member[sender].collection;
}

// 유저의 미니펫 컬렉션 데이터에서 현재 단계, 등록 수, 최대 수 계산하여 반환
function getMiniPetCollectionData(miniPetCollectionData, userName) {
	if (!miniPetCollectionData || !miniPetCollectionData.member) {
		return null;
	}

	var userData = miniPetCollectionData.member[userName];
	if (!userData || !userData.collection) {
		return null;
	}

	var collection = userData.collection;
	var registered = normalizeMiniPetCollectionRegistered(collection.registered);

	var registeredCount = 0;
	var maxCount = 0;

	for (var grade in registered) {
		if (!registered.hasOwnProperty(grade)) continue;
		maxCount++;
		if (registered[grade] === true) {
			registeredCount++;
		}
	}

	return {
		userName: userName,
		stage: parseInt(collection.stage || 0, 10), // 현재 단계
		completedStage: parseInt(collection.completedStage || 0, 10), // 완료된 단계
		registeredCount: registeredCount, // 현재 단계까지 등록된 컬렉션 수
		maxCount: maxCount // 현재 단계의 최대 컬렉션 수
	};
}

// 미니펫 컬렉션 랭킹 계산 및 정렬 함수 (단계 높은 순 → 등록 수 많은 순 → 닉네임 가나다순)
function getMiniPetCollectionRanking(miniPetCollectionData) {
	var ranking = [];

	if (!miniPetCollectionData || !miniPetCollectionData.member) {
		return ranking;
	}

	for (var userName in miniPetCollectionData.member) {
		if (!miniPetCollectionData.member.hasOwnProperty(userName)) continue;

		var row = getMiniPetCollectionData(miniPetCollectionData, userName);
		if (!row) continue;

		ranking.push(row);
	}

	ranking.sort(function (a, b) {
		// 현재 컬렉션 단계 높은 순
		if (b.stage !== a.stage) {
			return b.stage - a.stage;
		}

		// 현재 단계 등록 수 많은 순
		if (b.registeredCount !== a.registeredCount) {
			return b.registeredCount - a.registeredCount;
		}

		// 닉네임 가나다순
		return a.userName.localeCompare(b.userName, "ko");
	});

	return ranking;
}

// 미니펫 컬렉션 랭킹 메시지 생성 함수
function buildMiniPetCollectionRankingMessage(data, petData, guildData, miniPetCollectionData) {
	var ranking = getMiniPetCollectionRanking(miniPetCollectionData);

	if (!ranking.length) {
		return "💫 미니펫 컬렉션 순위 💫\n\n현재 컬렉션(등록된 컬렉션/최대 컬렉션 수치)\n\n❌ 컬렉션 데이터가 없습니다.";
	}

	var lines = [];
	lines.push("💫 미니펫 컬렉션 순위 💫");
	lines.push("");
	lines.push("현재 컬렉션(등록된 컬렉션/최대 컬렉션 수치)");
	lines.push("");

	for (var i = 0; i < ranking.length; i++) {
		if (i === 10) {
			lines.push(allsee);
		}

		var row = ranking[i];
		var rank = i + 1;
		var mark = getRankEmoji(rank);

		lines.push(mark + " " + checkRank(data, petData, guildData, row.userName) + " - 컬렉션+" + row.completedStage + "💫 (" + row.registeredCount + "/" + row.maxCount + ")");
	}

	return lines.join("\n");
}
